{{ config(
            materialized='table',
                post_hook={
                    "sql": "CREATE OR REPLACE TABLE SNITCH_DB.MAPLEMONK.CAPSULE_OVERVIEW_DASHBOARD AS WITH capsule_skus AS ( SELECT DISTINCT UPPER(TRIM(SKU)) AS SKU_GROUP, TRIM(COLLECTION) AS CAPSULE FROM SNITCH_DB.MAPLEMONK.COLLECTION_SKU_MAPPED_SHEET1 WHERE SKU IS NOT NULL AND COLLECTION IS NOT NULL ), capsule_launch AS ( SELECT * FROM VALUES (\'Street FC\', \'2026-06-23\'::DATE), (\'Street FC Plus\', \'2026-06-23\'::DATE), (\'Botanical Theme\', \'2026-07-11\'::DATE), (\'Embroided Shirts\', \'2026-07-16\'::DATE), (\'Golf Polo Theme\', \'2026-07-27\'::DATE), (\'Photo Print\', \'2026-08-06\'::DATE), (\'Try Less Denim\', \'2026-08-14\'::DATE), (\'Printed Shirts\', \'2026-09-04\'::DATE), (\'Luxe\', \'2026-09-18\'::DATE), (\'Technical\', \'2026-09-24\'::DATE), (\'Puffer\', \'2026-10-16\'::DATE) AS t(CAPSULE, LAUNCH_DATE) ), sales_base AS ( SELECT c.CAPSULE, UPPER(TRIM(h.SKU_GROUP)) AS SKU_GROUP, TO_DATE(h.DATE) AS SALES_DATE, CASE WHEN UPPER(h.CHANNEL) LIKE \'SNITCH - COCO%\' THEN \'Offline\' WHEN UPPER(h.CHANNEL) LIKE \'SNITCH - FOCO%\' THEN \'Offline\' WHEN UPPER(h.CHANNEL) LIKE \'SNITCH - COFO%\' THEN \'Offline\' WHEN UPPER(h.CHANNEL) IN ( \'MYNTRA\', \'AJIO\', \'AMAZON\', \'FLIPKART\', \'NYKAA\', \'TATACLIQ\', \'TATA CLIQ\' ) THEN \'Online\' WHEN LOWER(h.CHANNEL) IN (\'web\', \'web2\') THEN \'Online\' WHEN LOWER(h.CHANNEL) LIKE \'app%\' THEN \'Online\' ELSE \'Others\' END AS CHANNEL_TYPE, COALESCE(h.GROSS_QUANTITY, 0) AS UNITS_SOLD, COALESCE(h.GROSS_SALES, 0) AS GROSS_SALES, COALESCE(h.DISCOUNT_AMOUNT, 0) AS DISCOUNT FROM SNITCH_DB.MAPLEMONK.HORIZONTAL_SALES_CATEGORIES h INNER JOIN capsule_skus c ON UPPER(TRIM(h.SKU_GROUP)) = c.SKU_GROUP WHERE TO_DATE(h.DATE) < CURRENT_DATE() ), first_sale_ever AS ( SELECT CAPSULE, MIN(IFF(UNITS_SOLD > 0, SALES_DATE, NULL)) AS FIRST_SALE_DATE FROM sales_base GROUP BY CAPSULE ), capsule_dates AS ( SELECT f.CAPSULE, COALESCE(l.LAUNCH_DATE, f.FIRST_SALE_DATE) AS LAUNCH_DATE FROM first_sale_ever f LEFT JOIN capsule_launch l ON LOWER(TRIM(f.CAPSULE)) = LOWER(TRIM(l.CAPSULE)) ), first_sale AS ( SELECT s.CAPSULE, CASE WHEN LOWER(TRIM(s.CAPSULE)) = \'technical\' THEN MIN( IFF( s.UNITS_SOLD > 0 AND s.SALES_DATE >= DATEADD(DAY, -30, d.LAUNCH_DATE) AND s.SALES_DATE < d.LAUNCH_DATE, s.SALES_DATE, NULL ) ) ELSE MIN(IFF(s.UNITS_SOLD > 0, s.SALES_DATE, NULL)) END AS FIRST_SALE_DATE FROM sales_base s LEFT JOIN capsule_dates d ON LOWER(TRIM(s.CAPSULE)) = LOWER(TRIM(d.CAPSULE)) GROUP BY s.CAPSULE ), sales_from_first_sale AS ( SELECT s.CAPSULE, s.CHANNEL_TYPE, SUM(s.UNITS_SOLD) AS FIRST_SALE_TO_DATE_QTY FROM sales_base s INNER JOIN first_sale f ON s.CAPSULE = f.CAPSULE WHERE s.SALES_DATE >= f.FIRST_SALE_DATE AND s.SALES_DATE < CURRENT_DATE() GROUP BY s.CAPSULE, s.CHANNEL_TYPE ), sales_from_first_sale_overall AS ( SELECT s.CAPSULE, SUM(s.UNITS_SOLD) AS FIRST_SALE_TO_DATE_QTY FROM sales_base s INNER JOIN first_sale f ON s.CAPSULE = f.CAPSULE WHERE s.SALES_DATE >= f.FIRST_SALE_DATE AND s.SALES_DATE < CURRENT_DATE() GROUP BY s.CAPSULE ), sales AS ( SELECT CAPSULE, CHANNEL_TYPE, SUM(UNITS_SOLD) AS UNITS_SOLD, SUM(GROSS_SALES) AS GROSS_SALES, SUM(DISCOUNT) AS DISCOUNT FROM sales_base GROUP BY CAPSULE, CHANNEL_TYPE ), sales_overall AS ( SELECT CAPSULE, \'Overall\' AS CHANNEL_TYPE, SUM(UNITS_SOLD) AS UNITS_SOLD, SUM(GROSS_SALES) AS GROSS_SALES, SUM(DISCOUNT) AS DISCOUNT FROM sales_base GROUP BY CAPSULE ), last_30_sales AS ( SELECT CAPSULE, CHANNEL_TYPE, SUM(UNITS_SOLD) AS LAST_30_QTY FROM sales_base WHERE SALES_DATE >= DATEADD(DAY, -30, CURRENT_DATE()) AND SALES_DATE < CURRENT_DATE() GROUP BY CAPSULE, CHANNEL_TYPE ), last_30_overall AS ( SELECT CAPSULE, SUM(UNITS_SOLD) AS LAST_30_QTY FROM sales_base WHERE SALES_DATE >= DATEADD(DAY, -30, CURRENT_DATE()) AND SALES_DATE < CURRENT_DATE() GROUP BY CAPSULE ), sales_since_launch AS ( SELECT s.CAPSULE, s.CHANNEL_TYPE, SUM(s.UNITS_SOLD) AS LAUNCH_TO_DATE_QTY FROM sales_base s INNER JOIN capsule_dates d ON LOWER(TRIM(s.CAPSULE)) = LOWER(TRIM(d.CAPSULE)) WHERE s.SALES_DATE >= d.LAUNCH_DATE AND s.SALES_DATE < CURRENT_DATE() GROUP BY s.CAPSULE, s.CHANNEL_TYPE ), sales_since_launch_overall AS ( SELECT s.CAPSULE, SUM(s.UNITS_SOLD) AS LAUNCH_TO_DATE_QTY FROM sales_base s INNER JOIN capsule_dates d ON LOWER(TRIM(s.CAPSULE)) = LOWER(TRIM(d.CAPSULE)) WHERE s.SALES_DATE >= d.LAUNCH_DATE AND s.SALES_DATE < CURRENT_DATE() GROUP BY s.CAPSULE ), inventory AS ( SELECT c.CAPSULE, SUM(COALESCE(i.QTY_AVAILABLE, 0)) AS WH_INVENTORY, SUM(COALESCE(i.QTY_OFFLINE_AVAILABLE, 0)) AS STORE_INVENTORY FROM SNITCH_DB.MAPLEMONK.COGS_DAILY_SNAPSHOT i INNER JOIN capsule_skus c ON UPPER(TRIM(i.SKU_GROUP)) = c.SKU_GROUP WHERE i.DATE = ( SELECT MAX(DATE) FROM SNITCH_DB.MAPLEMONK.COGS_DAILY_SNAPSHOT ) GROUP BY c.CAPSULE ), inwards AS ( SELECT c.CAPSULE, SUM(COALESCE(p.INWARD_QTY, 0)) AS INWARD_QTY FROM capsule_skus c LEFT JOIN ( SELECT UPPER(TRIM( REVERSE(SUBSTRING( REVERSE(\"Item Type skuCode\"), CHARINDEX(\'-\', REVERSE(\"Item Type skuCode\")) + 1, LEN(\"Item Type skuCode\") )) )) AS SKU_GROUP, SUM(\"PUTAWAY_COMPLETED_QUANTITY\") AS INWARD_QTY FROM SNITCH_DB.MAPLEMONK.PUTAWAY_TRACKING WHERE LOWER(FINAL_TYPE) LIKE \'new%\' GROUP BY 1 ) p ON UPPER(TRIM(c.SKU_GROUP)) = p.SKU_GROUP GROUP BY c.CAPSULE ), mrp AS ( SELECT c.CAPSULE, MAX(m.MRP) AS MRP FROM capsule_skus c LEFT JOIN ( SELECT UPPER(TRIM( REVERSE(SUBSTRING( REVERSE(\"Item SkuCode\"), POSITION(\'-\' IN REVERSE(\"Item SkuCode\")) + 1 )) )) AS SKU_GROUP, MAX(MRP) AS MRP FROM SNITCH_DB.MAPLEMONK.SNITCH_FINAL_INVENTORY_WH2 GROUP BY 1 ) m ON UPPER(TRIM(c.SKU_GROUP)) = m.SKU_GROUP GROUP BY c.CAPSULE ), channel_data AS ( SELECT * FROM sales_overall UNION ALL SELECT CAPSULE, CHANNEL_TYPE, UNITS_SOLD, GROSS_SALES, DISCOUNT FROM sales WHERE CHANNEL_TYPE IN (\'Online\', \'Offline\') ), common AS ( SELECT cd.CAPSULE, cd.CHANNEL_TYPE, d.LAUNCH_DATE, fs.FIRST_SALE_DATE, DATEDIFF(DAY, d.LAUNCH_DATE, CURRENT_DATE()) AS DAYS_SINCE_LAUNCH, cd.UNITS_SOLD, cd.GROSS_SALES, cd.DISCOUNT, CASE WHEN cd.CHANNEL_TYPE = \'Overall\' THEN COALESCE(fsso.FIRST_SALE_TO_DATE_QTY, 0) ELSE COALESCE(fss.FIRST_SALE_TO_DATE_QTY, 0) END AS FIRST_SALE_TO_DATE_QTY, CASE WHEN cd.CHANNEL_TYPE = \'Overall\' THEN COALESCE(l30o.LAST_30_QTY, 0) ELSE COALESCE(l30.LAST_30_QTY, 0) END AS LAST_30_QTY, CASE WHEN cd.CHANNEL_TYPE = \'Overall\' THEN COALESCE(sslo.LAUNCH_TO_DATE_QTY, 0) ELSE COALESCE(ssl.LAUNCH_TO_DATE_QTY, 0) END AS LAUNCH_TO_DATE_QTY, COALESCE(i.WH_INVENTORY, 0) AS WH_INVENTORY, COALESCE(i.STORE_INVENTORY, 0) AS STORE_INVENTORY, COALESCE(i.WH_INVENTORY, 0) + COALESCE(i.STORE_INVENTORY, 0) AS INVENTORY_QTY, COALESCE(w.INWARD_QTY, 0) AS INWARD_QTY, COALESCE(m.MRP, 0) AS MRP, COALESCE(m.MRP, 0) * COALESCE(w.INWARD_QTY, 0) AS OPENING_GMV, COALESCE(m.MRP, 0) * ( COALESCE(i.WH_INVENTORY, 0) + COALESCE(i.STORE_INVENTORY, 0) ) AS INVENTORY_GMV, COALESCE(m.MRP, 0) * COALESCE(cd.UNITS_SOLD, 0) AS SOLD_GMV FROM channel_data cd LEFT JOIN capsule_dates d ON LOWER(TRIM(cd.CAPSULE)) = LOWER(TRIM(d.CAPSULE)) LEFT JOIN first_sale fs ON cd.CAPSULE = fs.CAPSULE LEFT JOIN sales_from_first_sale fss ON cd.CAPSULE = fss.CAPSULE AND cd.CHANNEL_TYPE = fss.CHANNEL_TYPE LEFT JOIN sales_from_first_sale_overall fsso ON cd.CAPSULE = fsso.CAPSULE LEFT JOIN last_30_sales l30 ON cd.CAPSULE = l30.CAPSULE AND cd.CHANNEL_TYPE = l30.CHANNEL_TYPE LEFT JOIN last_30_overall l30o ON cd.CAPSULE = l30o.CAPSULE LEFT JOIN sales_since_launch ssl ON cd.CAPSULE = ssl.CAPSULE AND cd.CHANNEL_TYPE = ssl.CHANNEL_TYPE LEFT JOIN sales_since_launch_overall sslo ON cd.CAPSULE = sslo.CAPSULE LEFT JOIN inventory i ON cd.CAPSULE = i.CAPSULE LEFT JOIN inwards w ON cd.CAPSULE = w.CAPSULE LEFT JOIN mrp m ON cd.CAPSULE = m.CAPSULE ) SELECT CAPSULE, CHANNEL_TYPE, LAUNCH_DATE, FIRST_SALE_DATE, DAYS_SINCE_LAUNCH, UNITS_SOLD, GROSS_SALES, DISCOUNT, ROUND( FIRST_SALE_TO_DATE_QTY * 100.0 / NULLIF(INWARD_QTY, 0), 2 ) AS PCT_SOLD, ROUND( CASE WHEN LOWER(TRIM(CAPSULE)) = \'technical\' THEN FIRST_SALE_TO_DATE_QTY * 100.0 / NULLIF(INWARD_QTY, 0) ELSE LAUNCH_TO_DATE_QTY * 100.0 / NULLIF(INWARD_QTY, 0) END, 2 ) AS STR, WH_INVENTORY, STORE_INVENTORY, INVENTORY_QTY, ROUND( INVENTORY_QTY * 100.0 / NULLIF(INWARD_QTY, 0), 2 ) AS INVENTORY_LEFT_PCT, INWARD_QTY, OPENING_GMV, INVENTORY_GMV, SOLD_GMV, ROUND( CASE WHEN DAYS_SINCE_LAUNCH < 30 THEN LAUNCH_TO_DATE_QTY * 100.0 / NULLIF(INWARD_QTY, 0) ELSE LAST_30_QTY * 100.0 / NULLIF(INWARD_QTY, 0) END, 2 ) AS STR_30D, ROUND( CASE WHEN DAYS_SINCE_LAUNCH = 0 THEN NULL WHEN DAYS_SINCE_LAUNCH < 30 THEN LEAST( ( LAUNCH_TO_DATE_QTY * 30.0 / NULLIF(DAYS_SINCE_LAUNCH, 0) ) * 100.0 / NULLIF(INWARD_QTY, 0), 100 ) ELSE LAST_30_QTY * 100.0 / NULLIF(INWARD_QTY, 0) END, 2 ) AS NORMALIZED_30_STR FROM common ORDER BY CAPSULE, CASE WHEN CHANNEL_TYPE = \'Overall\' THEN 1 WHEN CHANNEL_TYPE = \'Online\' THEN 2 WHEN CHANNEL_TYPE = \'Offline\' THEN 3 ELSE 4 END;",
                    "transaction": true
                }
            ) }}
            with sample_data as (

                select * from SNITCH_DB.information_schema.databases
            ),
            
            final as (
                select * from sample_data
            )
            select * from final
            